'use client';

import React from 'react';
import type { FileNode } from '@/types';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { AlertTriangle } from 'lucide-react';
import { Document, Page, pdfjs } from 'react-pdf';
import 'react-pdf/dist/esm/Page/AnnotationLayer.css';
import 'react-pdf/dist/esm/Page/TextLayer.css';

pdfjs.GlobalWorkerOptions.workerSrc = '/pdf.worker.min.mjs';

interface PdfViewerProps {
  selectedFile: FileNode | null;
  initialPage?: number;
  searchText?: string;
  searchJumpToken?: number;
}

function getPageTextSpans(pageRoot: HTMLElement): HTMLElement[] {
  const preferred = Array.from(
    pageRoot.querySelectorAll<HTMLElement>('.react-pdf__Page__textContent span[role="presentation"]')
  ).filter((el) => (el.textContent ?? '').trim().length > 0);

  if (preferred.length > 0) {
    return preferred;
  }

  return Array.from(
    pageRoot.querySelectorAll<HTMLElement>('.react-pdf__Page__textContent span')
  ).filter((el) => el.childElementCount === 0 && (el.textContent ?? '').trim().length > 0);
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function clearPageHighlights(pageRoot: HTMLElement) {
  const spans = Array.from(
    pageRoot.querySelectorAll<HTMLElement>('[data-search-highlighted="true"]')
  );

  for (const span of spans) {
    const original = span.dataset.searchOriginal;
    if (typeof original === 'string') {
      span.textContent = original;
    }
    delete span.dataset.searchHighlighted;
    delete span.dataset.searchOriginal;
  }
}

function scrollElementIntoContainer(container: HTMLDivElement | null, element: HTMLElement) {
  if (!container) {
    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
    return;
  }

  const containerRect = container.getBoundingClientRect();
  const targetRect = element.getBoundingClientRect();
  const nextTop =
    container.scrollTop +
    (targetRect.top - containerRect.top) -
    (container.clientHeight / 2 - targetRect.height / 2);

  container.scrollTo({
    top: Math.max(0, nextTop),
    behavior: 'smooth',
  });
}

function normalizeForSearchWithMap(input: string) {
  let normalized = '';
  const normToRaw: number[] = [];
  let lastWasSpace = true;

  for (let i = 0; i < input.length; i += 1) {
    const rawChar = input[i];

    if (rawChar === '\u00ad') {
      continue;
    }

    if (/\s/.test(rawChar) || rawChar === '\u00a0') {
      if (!lastWasSpace && normalized.length > 0) {
        normalized += ' ';
        normToRaw.push(i);
        lastWasSpace = true;
      }
      continue;
    }

    let canonical = rawChar
      .normalize('NFKC')
      .toLowerCase()
      .replace(/[\u2010-\u2015]/g, '-')
      .replace(/[’‘]/g, "'")
      .replace(/[“”«»„]/g, '"');

    if (!canonical) {
      continue;
    }

    for (const ch of canonical) {
      normalized += ch;
      normToRaw.push(i);
    }

    lastWasSpace = false;
  }

  if (normalized.endsWith(' ')) {
    normalized = normalized.slice(0, -1);
    normToRaw.pop();
  }

  return { normalized, normToRaw };
}

function normalizeForSearch(input: string): string {
  return normalizeForSearchWithMap(input.trim()).normalized;
}

function highlightTextOnPdfPage(
  pageRoot: HTMLElement,
  searchText: string,
  container: HTMLDivElement | null
): boolean {
  const query = normalizeForSearch(searchText);
  if (!query) {
    return false;
  }

  const textSpans = getPageTextSpans(pageRoot);
  if (textSpans.length === 0) {
    return false;
  }

  const spansWithText = textSpans.map((span) => ({
    span,
    text: span.textContent || '',
  }));

  const fullText = spansWithText.map((item) => item.text).join('');
  if (!fullText) {
    return false;
  }

  const { normalized: normalizedText, normToRaw } = normalizeForSearchWithMap(fullText);
  const matchStartNorm = normalizedText.indexOf(query);
  if (matchStartNorm === -1) {
    return false;
  }

  const matchEndNorm = matchStartNorm + query.length - 1;
  const matchStartRaw = normToRaw[matchStartNorm];
  const matchEndRawExclusive = (normToRaw[matchEndNorm] ?? matchStartRaw) + 1;

  let rawCursor = 0;
  let firstHighlightedSpan: HTMLElement | null = null;

  for (const { span, text } of spansWithText) {
    const spanStart = rawCursor;
    const spanEnd = rawCursor + text.length;
    rawCursor = spanEnd;

    if (!text) {
      continue;
    }

    if (spanEnd <= matchStartRaw || spanStart >= matchEndRawExclusive) {
      continue;
    }

    const localStart = Math.max(0, matchStartRaw - spanStart);
    const localEnd = Math.min(text.length, matchEndRawExclusive - spanStart);
    if (localStart >= localEnd) {
      continue;
    }

    const before = escapeHtml(text.slice(0, localStart));
    const match = escapeHtml(text.slice(localStart, localEnd));
    const after = escapeHtml(text.slice(localEnd));

    span.dataset.searchOriginal = text;
    span.dataset.searchHighlighted = 'true';
    span.innerHTML = `${before}<mark class="bg-yellow-200 text-yellow-900 font-bold px-0.5 rounded">${match}</mark>${after}`;

    if (!firstHighlightedSpan) {
      firstHighlightedSpan = span;
    }
  }

  if (!firstHighlightedSpan) {
    return false;
  }

  scrollElementIntoContainer(container, firstHighlightedSpan);
  return true;
}

const PdfViewer: React.FC<PdfViewerProps> = ({
  selectedFile,
  initialPage = 1,
  searchText,
  searchJumpToken = 0,
}) => {
  const [numPages, setNumPages] = React.useState<number>(0);
  const [zoom, setZoom] = React.useState(1.0);
  const pageRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const containerRef = React.useRef<HTMLDivElement | null>(null);
  const highlightRunIdRef = React.useRef(0);

  const handleZoomIn = () => setZoom((z) => Math.min(2.0, +(z + 0.1).toFixed(2)));
  const handleZoomOut = () => setZoom((z) => Math.max(0.5, +(z - 0.1).toFixed(2)));

  React.useEffect(() => {
    setNumPages(0);
    pageRefs.current = [];
    highlightRunIdRef.current += 1;
  }, [selectedFile?.path]);

  React.useEffect(() => {
    if (numPages === 0 || initialPage < 1 || initialPage > numPages) {
      return;
    }

    let attempts = 0;
    const maxAttempts = 25;
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    let cancelled = false;

    const tryScrollToPage = () => {
      if (cancelled) return;

      const pageRef = pageRefs.current[initialPage - 1];
      const container = containerRef.current;

      if (pageRef) {
        if (container) {
          container.scrollTo({ top: pageRef.offsetTop, behavior: 'smooth' });
        } else {
          pageRef.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
        return;
      }

      attempts += 1;
      if (attempts < maxAttempts) {
        timeoutId = setTimeout(tryScrollToPage, 120);
      }
    };

    tryScrollToPage();

    return () => {
      cancelled = true;
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [numPages, initialPage, selectedFile?.path, searchJumpToken]);

  React.useEffect(() => {
    for (const pageRef of pageRefs.current) {
      if (pageRef) {
        clearPageHighlights(pageRef);
      }
    }

    const query = searchText?.trim();
    if (!query || numPages === 0 || initialPage < 1 || initialPage > numPages) {
      return;
    }

    const runId = ++highlightRunIdRef.current;
    let attempts = 0;
    const maxAttempts = 30;
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    let cancelled = false;

    const tryHighlight = () => {
      if (cancelled || highlightRunIdRef.current !== runId) {
        return;
      }

      const pageRef = pageRefs.current[initialPage - 1];
      if (!pageRef) {
        attempts += 1;
        if (attempts < maxAttempts) {
          timeoutId = setTimeout(tryHighlight, 120);
        }
        return;
      }

      const done = highlightTextOnPdfPage(pageRef, query, containerRef.current);
      if (!done) {
        attempts += 1;
        if (attempts < maxAttempts) {
          timeoutId = setTimeout(tryHighlight, 120);
        }
      }
    };

    tryHighlight();

    return () => {
      cancelled = true;
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [searchText, initialPage, numPages, selectedFile?.path, zoom, searchJumpToken]);

  if (!selectedFile) {
    return (
      <Card className="h-full flex items-center justify-center shadow-lg">
        <CardContent className="text-center">
          <p className="text-lg text-muted-foreground p-8">Select a file to view its content.</p>
        </CardContent>
      </Card>
    );
  }

  if (selectedFile.type === 'folder' || !selectedFile.path) {
    return (
      <Card className="h-full flex items-center justify-center shadow-lg">
        <CardContent className="text-center p-8">
          <AlertTriangle className="mx-auto h-12 w-12 text-destructive mb-4" />
          <p className="text-lg text-destructive-foreground">Cannot display this item.</p>
          <p className="text-sm text-muted-foreground">This is a folder or the file path is missing.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="h-full flex flex-col shadow-lg overflow-hidden">
      <CardHeader>
        <CardTitle className="font-headline text-2xl truncate">{selectedFile.name}</CardTitle>
        <div className="flex gap-2 mt-2">
          <button
            className="px-2 py-1 rounded bg-gray-200 hover:bg-gray-300"
            onClick={handleZoomOut}
            disabled={zoom <= 0.5}
          >
            -
          </button>
          <span className="text-sm w-16 text-center">{Math.round(zoom * 100)}%</span>
          <button
            className="px-2 py-1 rounded bg-gray-200 hover:bg-gray-300"
            onClick={handleZoomIn}
            disabled={zoom >= 2.0}
          >
            +
          </button>
        </div>
      </CardHeader>
      <CardContent
        ref={containerRef}
        className="flex-1 p-0 relative overflow-auto max-h-[80vh] w-full flex justify-center"
      >
        <Document
          file={selectedFile.path}
          onLoadSuccess={({ numPages: loadedPages }) => {
            setNumPages(loadedPages);
          }}
          loading={<div className="p-8 text-center">Загрузка PDF...</div>}
          error={<div className="p-8 text-center text-destructive">Ошибка загрузки PDF</div>}
        >
          {Array.from(new Array(numPages), (_, index) => (
            <Page
              key={`page_${index + 1}`}
              pageNumber={index + 1}
              width={800 * zoom}
              inputRef={(ref) => {
                pageRefs.current[index] = ref;
              }}
            />
          ))}
        </Document>
      </CardContent>
    </Card>
  );
};

export default PdfViewer;
